    // Assert — real rmSync ran so the dir is gone, then clone was called
    expect(fs.existsSync(cacheDir)).toBe(false);
    expect(mockGit.clone).toHaveBeenCalledWith(TEST_URL, cacheDir, [
      '--depth',
      '1',
      '--branch',
      BRANCH,
    ]);
  });

  it('throws an error containing "Failed to clone repository" when clone rejects', async () => {
    // Arrange — guarantee cacheDir is absent
    const cacheDir = getCacheDir(TEST_URL);
    fs.rmSync(cacheDir, { recursive: true, force: true });
    mockGit.clone.mockRejectedValue(new Error('authentication required'));

    // Act / Assert
    await expect(ensureCached(TEST_URL, BRANCH)).rejects.toThrow('Failed to clone repository');
  });

import * as crypto from 'node:crypto';
import * as fs from 'node:fs';
import * as path from 'node:path';
import fg from 'fast-glob';
import { resolvePath } from './config';
import type { ManifestEntry } from './types';

function hasErrorCode(error: unknown, code: string): boolean {
  return error instanceof Error && 'code' in error && error.code === code;
}

function resolveExistingPath(filePath: string): string {
  let currentPath = path.resolve(filePath);
  const unresolvedSegments: string[] = [];

  while (true) {
    try {
      return path.join(fs.realpathSync.native(currentPath), ...unresolvedSegments.reverse());
    } catch (error) {
      if (!hasErrorCode(error, 'ENOENT')) {
        throw error;
      }

      try {
        fs.lstatSync(currentPath);
      } catch (lstatError) {
        if (!hasErrorCode(lstatError, 'ENOENT')) {
          throw lstatError;
        }

        const parentPath = path.dirname(currentPath);
        if (parentPath === currentPath) {
          throw error;
        }

        unresolvedSegments.push(path.basename(currentPath));
        currentPath = parentPath;
        continue;
      }

      throw error;
    }
  }
}

function isPathWithin(filePath: string, containingDir: string): boolean {
  const relativePath = path.relative(containingDir, filePath);

  return (
    relativePath === '' ||
    (!path.isAbsolute(relativePath) &&
      relativePath !== '..' &&
      !relativePath.startsWith(`..${path.sep}`))
  );
}

function assertNoEscapingSymlinks(filePath: string, label: string): void {
  const resolvedPath = path.resolve(filePath);
  const root = path.parse(resolvedPath).root;
  let currentPath = root;

  for (const segment of resolvedPath.slice(root.length).split(path.sep)) {
    if (segment === '') {
      continue;
    }

    const nextPath = path.join(currentPath, segment);
    let stats: fs.Stats;
    try {
      stats = fs.lstatSync(nextPath);
    } catch (error) {
      if (hasErrorCode(error, 'ENOENT')) {
        return;
      }
      throw error;
    }

    if (stats.isSymbolicLink()) {
      const canonicalParent = resolveExistingPath(currentPath);
      const canonicalTarget = resolveExistingPath(nextPath);
      if (!isPathWithin(canonicalTarget, canonicalParent)) {
        throw new Error(`${label} escapes the expected directory boundary.`);
      }
    }

    currentPath = nextPath;
  }
}

/**
 * Returns the canonical path if it is inside `containingDir`; otherwise, throws.
 */
export function assertPathWithin(filePath: string, containingDir: string, label: string): string {
  const resolved = resolveExistingPath(filePath);
  const base = resolveExistingPath(containingDir);

  if (!isPathWithin(resolved, base)) {
    throw new Error(`${label} escapes the expected directory boundary.`);
  }

  return resolved;
}

export function assertDestinationPath(filePath: string, label: string): string {
  const resolvedPath = path.resolve(filePath);
  assertNoEscapingSymlinks(resolvedPath, label);
  const canonicalPath = assertPathWithin(resolvedPath, path.dirname(resolvedPath), label);

  try {
    if (fs.lstatSync(resolvedPath).isSymbolicLink()) {
      throw new Error(`${label} is a symbolic link.`);
    }
  } catch (error) {
    if (!hasErrorCode(error, 'ENOENT')) {
      throw error;
    }
  }

  return canonicalPath;
}

export function assertDirectoryCopyPaths(
  sourceDir: string,
  destinationDir: string,
  sourceRoot: string,
  destinationRoot: string,
): void {
  assertPathWithin(sourceDir, sourceRoot, `Source path "${sourceDir}"`);
  assertPathWithin(destinationDir, destinationRoot, `Destination path "${destinationDir}"`);

  for (const entry of fs.readdirSync(sourceDir, { withFileTypes: true })) {
    const sourcePath = path.join(sourceDir, entry.name);
    const destinationPath = path.join(destinationDir, entry.name);

    assertPathWithin(sourcePath, sourceRoot, `Source path "${sourcePath}"`);
    assertPathWithin(destinationPath, destinationRoot, `Destination path "${destinationPath}"`);

    if (entry.isDirectory()) {
      assertDirectoryCopyPaths(sourcePath, destinationPath, sourceRoot, destinationRoot);
    }
  }
}

function copyDirectoryContents(
  sourceDir: string,
  destinationDir: string,
  sourceRoot: string,
  destinationRoot: string,
  activeDirectories = new Set<string>(),
): void {
  const canonicalSourceDir = assertPathWithin(sourceDir, sourceRoot, `Source path "${sourceDir}"`);
  const canonicalDestinationDir = assertPathWithin(
    destinationDir,
    destinationRoot,
    `Destination path "${destinationDir}"`,
  );

  if (isPathWithin(canonicalDestinationDir, canonicalSourceDir)) {
    throw new Error(
      `Destination directory "${destinationDir}" must not be inside source directory "${sourceDir}".`,
    );
  }

  if (activeDirectories.has(canonicalSourceDir)) {
    throw new Error(`Source directory "${sourceDir}" contains a circular symbolic link.`);
  }

  activeDirectories.add(canonicalSourceDir);
  fs.mkdirSync(canonicalDestinationDir, { recursive: true });

  try {
    for (const entry of fs.readdirSync(canonicalSourceDir, { withFileTypes: true })) {
      const sourcePath = path.join(canonicalSourceDir, entry.name);
      const destinationPath = path.join(canonicalDestinationDir, entry.name);
      const canonicalSourcePath = assertPathWithin(
        sourcePath,
        sourceRoot,
        `Source path "${sourcePath}"`,
      );
      const canonicalDestinationPath = assertPathWithin(
        destinationPath,
        destinationRoot,
        `Destination path "${destinationPath}"`,
      );
      const stats = fs.statSync(canonicalSourcePath);

      if (stats.isDirectory()) {
        copyDirectoryContents(
          canonicalSourcePath,
          canonicalDestinationPath,
          sourceRoot,
          destinationRoot,
          activeDirectories,
        );
      } else if (stats.isFile()) {
        fs.copyFileSync(canonicalSourcePath, canonicalDestinationPath);
      } else {
        throw new Error(`Source path "${sourcePath}" cannot be copied.`);
      }
    }
  } finally {
    activeDirectories.delete(canonicalSourceDir);
  }
}

/**
 * Returns SHA-256 hash of file contents, or null if file doesn't exist.
 */
export function fileHash(filePath: string): string | null {
  try {
    const content = fs.readFileSync(filePath);
    return crypto.createHash('sha256').update(content).digest('hex');
  } catch {
    return null;
  }
}

/** Returns true if the source path contains any glob metacharacter. */
export function isGlobPattern(source: string): boolean {
  return /[*?[\]{}]/.test(source);
}

/**
 * Returns the leading non-glob path segments joined with '/'.
 * e.g. 'skills/canvas/** /*.md' → 'skills/canvas'
 *      '*.md'                   → '.'
 */
export function globBase(pattern: string): string {
  const segments = pattern.split('/');
  const base: string[] = [];
  for (const seg of segments) {
    if (/[*?[\]{}]/.test(seg)) break;
    base.push(seg);
  }
  const result = base.join('/');
  return result.length > 0 ? result : '.';
}

/**
 * Syncs a single entry from its cached repo location to its destination.
 */
export async function syncEntry(
  entry: ManifestEntry,
  cacheDir: string,
): Promise<'updated' | 'unchanged'> {
  const destPath = resolvePath(entry.destination);

  // Glob pattern: expand matches and copy each file preserving relative structure
  if (isGlobPattern(entry.source)) {
    const base = globBase(entry.source);
    const absBase = path.join(cacheDir, base);
    assertPathWithin(absBase, cacheDir, `Glob base "${base}"`);
    const matches = fg.sync(entry.source, { cwd: cacheDir, absolute: true, onlyFiles: true });

    if (matches.length === 0) {
      process.stderr.write(`Warning: glob "${entry.source}" matched no files in cache.\n`);
      return 'unchanged';
    }

    const destinationRoot = assertDestinationPath(
      destPath,
      `Destination path "${entry.destination}"`,
    );

    let anyUpdated = false;
    for (const absMatch of matches) {
      const sourcePath = assertPathWithin(absMatch, cacheDir, `Glob match "${absMatch}"`);
      const relPath = path.relative(absBase, absMatch);
      const destFile = path.join(destinationRoot, relPath);
      const canonicalDestFile = assertPathWithin(
        destFile,
        destinationRoot,
        `Destination file "${relPath}"`,
      );

      const sourceDigest = fileHash(sourcePath);
      const destDigest = fileHash(canonicalDestFile);

      if (sourceDigest !== null && sourceDigest === destDigest) {
        continue;
      }

      fs.mkdirSync(path.dirname(canonicalDestFile), { recursive: true });
      const sourceToCopy = assertPathWithin(absMatch, cacheDir, `Glob match "${absMatch}"`);
      const destinationToCopy = assertPathWithin(
        destFile,
        destinationRoot,
        `Destination file "${relPath}"`,
      );
      fs.copyFileSync(sourceToCopy, destinationToCopy);
      anyUpdated = true;
    }
    return anyUpdated ? 'updated' : 'unchanged';
  }

  const sourcePath = path.join(cacheDir, entry.source);
  const canonicalSourcePath = assertPathWithin(
    sourcePath,
    cacheDir,
    `Source path "${entry.source}"`,
  );
  const canonicalDestinationPath = assertDestinationPath(
    destPath,
    `Destination path "${entry.destination}"`,
  );

  let sourceStat: fs.Stats;
  try {
    sourceStat = fs.statSync(canonicalSourcePath);
  } catch {
    throw new Error(
      `Source path "${entry.source}" does not exist in cache "${cacheDir}" (resolved: "${canonicalSourcePath}").`,
    );
  }

  if (sourceStat.isFile()) {
    const sourceForHash = assertPathWithin(sourcePath, cacheDir, `Source path "${entry.source}"`);
    const destinationForHash = assertDestinationPath(
      destPath,
      `Destination path "${entry.destination}"`,
    );
    const sourceDigest = fileHash(sourceForHash);
    const destinationDigest = fileHash(destinationForHash);

    if (sourceDigest !== null && sourceDigest === destinationDigest) {
      return 'unchanged';
    }

    fs.mkdirSync(path.dirname(destinationForHash), { recursive: true });
    const sourceToCopy = assertPathWithin(sourcePath, cacheDir, `Source path "${entry.source}"`);
    const destinationToCopy = assertDestinationPath(
      destPath,
      `Destination path "${entry.destination}"`,
    );
    fs.copyFileSync(sourceToCopy, destinationToCopy);
    return 'updated';
  }

  if (sourceStat.isDirectory()) {
    fs.mkdirSync(canonicalDestinationPath, { recursive: true });
    const sourceToCopy = assertPathWithin(sourcePath, cacheDir, `Source path "${entry.source}"`);
    const destinationToCopy = assertDestinationPath(
      destPath,
      `Destination path "${entry.destination}"`,
    );
    assertDirectoryCopyPaths(sourceToCopy, destinationToCopy, cacheDir, destinationToCopy);
    copyDirectoryContents(sourceToCopy, destinationToCopy, cacheDir, destinationToCopy);
    return 'updated';
  }

  throw new Error(
    `Source path "${sourcePath}" in cache is neither a regular file nor a directory and cannot be synced.`,
  );
}

import * as crypto from 'node:crypto';
import * as fs from 'node:fs';
import * as path from 'node:path';
import fg from 'fast-glob';
import { getCacheDir } from '../cache';
import { requireManifest, resolvePath } from '../config';
import {
  assertDestinationPath,
  assertDirectoryCopyPaths,
  assertPathWithin,
  fileHash,
  globBase,
  isGlobPattern,
} from '../sync';
import type { ManifestEntry, StatusResult } from '../types';

function collectDirectoryEntries(
  rootDir: string,
  currentDir: string,
  containmentRoot: string,
  entries: string[],
  activeDirectories: Set<string>,
): void {
  const canonicalDir = assertPathWithin(
    currentDir,
    containmentRoot,
    `Directory path "${currentDir}"`,
  );
  if (activeDirectories.has(canonicalDir)) {
    throw new Error(`Directory "${currentDir}" contains a circular symbolic link.`);
  }

  activeDirectories.add(canonicalDir);
  const children = fs.readdirSync(canonicalDir, { withFileTypes: true });

  try {
    for (const child of children) {
      const absolutePath = path.join(currentDir, child.name);
      const canonicalPath = assertPathWithin(
        absolutePath,
        containmentRoot,
        `Directory entry "${absolutePath}"`,
      );
      const stats = fs.statSync(canonicalPath);

      if (stats.isDirectory()) {
        collectDirectoryEntries(rootDir, absolutePath, containmentRoot, entries, activeDirectories);
        continue;
      }

      if (!stats.isFile()) {
        continue;
      }

      const relativePath = path.relative(rootDir, absolutePath).split(path.sep).join('/');
      const digest = fileHash(canonicalPath) ?? '';
      entries.push(`${relativePath}:${digest}`);
    }
  } finally {
    activeDirectories.delete(canonicalDir);
  }
}

function directoryHash(dir: string, containmentRoot: string): string {
  const pairs: string[] = [];
  collectDirectoryEntries(dir, dir, containmentRoot, pairs, new Set());
  pairs.sort();

  const combined = pairs.join('\n');
  return crypto.createHash('sha256').update(combined).digest('hex');
}

function stateLabel(state: StatusResult['state']): string {
  if (state === 'outdated') {
    return '!outdated';
  }

  if (state === 'missing') {
    return '?missing';
  }

  return 'current';
}

export function determineState(entry: ManifestEntry): StatusResult['state'] {
  const cacheDir = getCacheDir(entry.repo);
  let destinationPath = resolvePath(entry.destination);

  if (!fs.existsSync(cacheDir)) {
    return 'missing';
  }

  try {
    destinationPath = assertDestinationPath(
      destinationPath,
      `Destination path "${entry.destination}"`,
    );
  } catch {
    return 'missing';
  }

  // Glob pattern: expand and check each matched file
  if (isGlobPattern(entry.source)) {
    if (!fs.existsSync(cacheDir)) return 'missing';
    const base = globBase(entry.source);
    const absBase = path.join(cacheDir, base);
    try {
      assertPathWithin(absBase, cacheDir, `Glob base "${base}"`);
    } catch {
      return 'missing';
    }
    const matches = fg.sync(entry.source, { cwd: cacheDir, absolute: true, onlyFiles: true });
    if (matches.length === 0) return 'missing';
    for (const absMatch of matches) {
      let sourceMatch: string;
      try {
        sourceMatch = assertPathWithin(absMatch, cacheDir, `Glob match "${absMatch}"`);
      } catch {
        return 'missing';
      }
      const relPath = path.relative(absBase, absMatch);
      const destFile = path.join(destinationPath, relPath);
      let canonicalDestFile: string;
      try {
        canonicalDestFile = assertPathWithin(
          destFile,
          destinationPath,
          `Destination file "${relPath}"`,
        );
      } catch {
        return 'missing';
      }
      if (!fs.existsSync(canonicalDestFile)) return 'missing';
      const sourceDigest = fileHash(sourceMatch);
      const destDigest = fileHash(canonicalDestFile);
      if (sourceDigest !== destDigest) return 'outdated';
    }
    return 'current';
  }

  let sourcePath: string;
  try {
    sourcePath = assertPathWithin(
      path.join(cacheDir, entry.source),
      cacheDir,
      `Source path "${entry.source}"`,
    );
  } catch {
    return 'missing';
  }

  if (!fs.existsSync(destinationPath)) {
    return 'missing';
  }

  if (!fs.existsSync(sourcePath)) {
    return 'missing';
  }

  let sourceStat: fs.Stats;
  try {
    sourceStat = fs.statSync(sourcePath);
  } catch {
    return 'missing';
  }

  if (sourceStat.isFile()) {
    const sourceDigest = fileHash(sourcePath);
    const destinationDigest = fileHash(destinationPath);
    return sourceDigest !== null && sourceDigest === destinationDigest ? 'current' : 'outdated';
  }

  if (sourceStat.isDirectory()) {
    try {
      if (!fs.statSync(destinationPath).isDirectory()) {
        return 'outdated';
      }
    } catch {
      return 'missing';
    }

    try {
      assertDirectoryCopyPaths(sourcePath, destinationPath, cacheDir, destinationPath);
    } catch {
      return 'missing';
    }

    try {
      const sourceDigest = directoryHash(sourcePath, cacheDir);
      const destinationDigest = directoryHash(destinationPath, destinationPath);
      return sourceDigest === destinationDigest ? 'current' : 'outdated';
    } catch {
      return 'missing';
    }
  }

  return 'missing';
}

export async function statusCommand(): Promise<void> {
  const { manifest } = requireManifest();

  if (manifest.entries.length === 0) {
    console.log("No entries tracked. Use 'dfiles add' to start.");
    return;
  }

  const results: StatusResult[] = manifest.entries.map((entry) => ({
    entry,
    state: determineState(entry),
  }));

  const headers = ['ID', 'STATE', 'SOURCE', 'DESTINATION'] as const;
  const rows = results.map((result) => [
    result.entry.id,
    stateLabel(result.state),
    result.entry.source,
    result.entry.destination,
  ]);

  const widths = headers.map((header, index) => {
    return Math.max(header.length, ...rows.map((row) => row[index].length));
  });

  const formatRow = (values: readonly string[]): string => {
    return values.map((value, index) => value.padEnd(widths[index])).join('  ');
  };

  console.log(formatRow(headers));

  const separatorWidth = widths.reduce((sum, width) => sum + width, 0) + 2 * (headers.length - 1);
  console.log('─'.repeat(separatorWidth));

  for (const row of rows) {
    console.log(formatRow(row));
  }
}

import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import type { Manifest } from './types';

export const MANIFEST_FILENAME = 'dfiles.json';

/**
 * Replaces leading ~ with os.homedir(), then path.resolve().
 * This is the single cross-platform path normalizer used everywhere.
 */
export function resolvePath(p: string): string {
  const expandedPath =
    p === '~'
      ? os.homedir()
      : p.startsWith('~/') || p.startsWith('~\\')
        ? path.join(os.homedir(), p.slice(2))
        : p;

  return path.resolve(expandedPath);
}

/**
 * Walks up from process.cwd() checking for dfiles.json at each level.
 * Returns the directory path that contains dfiles.json, or null if not found.
 * Stops at filesystem root.
 */
export function findManifestDir(): string | null {
  let current = process.cwd();

  while (true) {
    const manifestPath = path.join(current, MANIFEST_FILENAME);
    if (fs.existsSync(manifestPath)) {
      try {
        if (fs.statSync(manifestPath).isFile()) {
          return current;
        }
      } catch {
        // Ignore filesystem race conditions and continue walking upward.
      }
    }

    const parent = path.dirname(current);
    if (current === parent) {
      return null;
    }

    current = parent;
  }
}

function isManifest(value: unknown): value is Manifest {
  if (!value || typeof value !== 'object') {
    return false;
  }

  const maybeManifest = value as { version?: unknown; entries?: unknown };
  if (maybeManifest.version !== 1 || !Array.isArray(maybeManifest.entries)) {
    return false;
  }

  return maybeManifest.entries.every((entry) => {
    if (!entry || typeof entry !== 'object') {
      return false;
    }

    const candidate = entry as { [key: string]: unknown };
    return (
      typeof candidate.id === 'string' &&
      typeof candidate.repo === 'string' &&
      typeof candidate.branch === 'string' &&
      typeof candidate.source === 'string' &&
      typeof candidate.destination === 'string'
    );
  });
}

/**
 * Reads and JSON-parses dfiles.json from `dir`.
 * Throws a descriptive error if not found or malformed.
 */
export function loadManifest(dir: string): Manifest {
  const manifestPath = path.join(dir, MANIFEST_FILENAME);

  if (!fs.existsSync(manifestPath)) {
    throw new Error(
      `Manifest file not found at "${manifestPath}". Run "dfiles init" in your project root first.`,
    );
  }

  let parsed: unknown;
  try {
    const raw = fs.readFileSync(manifestPath, 'utf8');
    parsed = JSON.parse(raw);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`Failed to read or parse manifest at "${manifestPath}": ${message}`);
  }

  if (!isManifest(parsed)) {
    throw new Error(
      `Manifest at "${manifestPath}" is malformed. Expected shape: { "version": 1, "entries": ManifestEntry[] }.`,
    );
  }

  return parsed;
}

/**
 * Writes JSON.stringify(manifest, null, 2) to dfiles.json in `dir`.
 */
export function saveManifest(dir: string, manifest: Manifest): void {
  const manifestPath = path.join(dir, MANIFEST_FILENAME);
  fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 2), 'utf8');
}

/**
 * Calls findManifestDir(), throws actionable error if null.
 * Used by all commands except `init`.
 */
export function requireManifest(): { dir: string; manifest: Manifest } {
  const dir = findManifestDir();
  if (!dir) {
    throw new Error(
      `No ${MANIFEST_FILENAME} found in this directory or any parent directory. Run "dfiles init" in your project root first.`,
    );
  }

  return {
    dir,
    manifest: loadManifest(dir),
  };
}

import * as crypto from 'node:crypto';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import simpleGit from 'simple-git';

export const CACHE_BASE = path.join(os.homedir(), '.dfiles', 'cache');

/**
 * SHA-256 of repoUrl, first 16 hex chars. Deterministic, collision-resistant.
 */
export function getRepoHash(repoUrl: string): string {
  return crypto.createHash('sha256').update(repoUrl).digest('hex').slice(0, 16);
}

/**
 * Returns path.join(CACHE_BASE, getRepoHash(repoUrl))
 */
export function getCacheDir(repoUrl: string): string {
  return path.join(CACHE_BASE, getRepoHash(repoUrl));
}

function toErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

/**
 * Main function: ensures repo is cloned and up-to-date.
 *
 * Steps:
 * 1. fs.mkdirSync(CACHE_BASE, { recursive: true })
 * 2. Check if cacheDir exists AND is a valid git repo (use simpleGit(cacheDir).checkIsRepo())
 *    - If checkIsRepo throws or the dir doesn't exist: treat as "not cached"
 * 3. If NOT cached:
 *    - If cacheDir exists but is corrupt: delete it first (fs.rmSync with { recursive: true, force: true })
 *    - Clone: await simpleGit().clone(repoUrl, cacheDir, ['--depth', '1', '--branch', branch])
 * 4. If cached:
 *    - const git = simpleGit(cacheDir)
 *    - await git.fetch('origin', branch)
 *    - await git.checkout(branch)
 *    - await git.pull('origin', branch)
 * 5. Returns cacheDir
 *
 * Errors from simple-git are re-thrown with context.
 */
export async function ensureCached(repoUrl: string, branch: string): Promise<string> {
  fs.mkdirSync(CACHE_BASE, { recursive: true });

  const cacheDir = getCacheDir(repoUrl);
  const cacheDirExists = fs.existsSync(cacheDir);
  let isCached = false;

  if (cacheDirExists) {
    try {
      const stat = fs.statSync(cacheDir);
      if (stat.isDirectory()) {
        isCached = await simpleGit(cacheDir).checkIsRepo();
      }
    } catch {
      isCached = false;
    }
  }

  if (!isCached) {
    if (cacheDirExists) {
      fs.rmSync(cacheDir, { recursive: true, force: true });
    }

    try {
      await simpleGit().clone(repoUrl, cacheDir, ['--depth', '1', '--branch', branch]);
    } catch (error) {
      throw new Error(
        `Failed to clone repository "${repoUrl}" (branch "${branch}") into cache "${cacheDir}": ${toErrorMessage(error)}`,
      );
    }

    return cacheDir;
  }

  const git = simpleGit(cacheDir);

  // Step 1: clear any stale index lock left by a previously interrupted operation
  const lockFile = path.join(cacheDir, '.git', 'index.lock');
  if (fs.existsSync(lockFile)) {
    try {
      fs.rmSync(lockFile, { force: true });
    } catch {
      // ignore — if we can't remove the lock, the subsequent git operation will
      // surface its own error (e.g. "Unable to lock index file")
    }
  }

  // Step 2: fetch with --depth 1 to avoid deepening the shallow clone
  try {
    await git.fetch('origin', branch, ['--depth', '1']);
  } catch (error) {
    const msg = toErrorMessage(error);
    // Branch deleted or renamed on remote — re-clone won't help either, surface clearly
    if (/couldn't find remote ref|invalid refspec/i.test(msg)) {
      throw new Error(
        `Branch "${branch}" not found on remote "${repoUrl}". It may have been deleted or renamed.`,
      );
    }
    throw new Error(
      `Failed to update cached repository "${repoUrl}" (branch "${branch}") at "${cacheDir}": ${msg}`,
    );
  }

  // Step 3: checkout the branch (create local tracking branch if needed, reset if detached)
  try {
    await git.checkout(['-B', branch, `origin/${branch}`]);
  } catch (error) {
    throw new Error(
      `Failed to checkout branch "${branch}" in cached repository "${repoUrl}" at "${cacheDir}": ${toErrorMessage(error)}`,
    );
  }

  // Step 4: try pull; on fast-forward failure use reset --hard (no extra network call)
  try {
    await git.pull('origin', branch);
  } catch (error) {
    const msg = toErrorMessage(error);
    if (/not possible to fast.forward|not a fast.forward/i.test(msg)) {
      // Primary recovery: reset to the already-fetched remote tip
      try {
        await git.reset(['--hard', `origin/${branch}`]);
      } catch {
        // Last resort: corrupt local repo — wipe and re-clone
        fs.rmSync(cacheDir, { recursive: true, force: true });
        try {
          await simpleGit().clone(repoUrl, cacheDir, ['--depth', '1', '--branch', branch]);
        } catch (cloneError) {
          throw new Error(
            `Failed to re-clone repository "${repoUrl}" (branch "${branch}") after unrecoverable cache state: ${toErrorMessage(cloneError)}`,
          );
        }
      }
    } else {
      throw new Error(
        `Failed to update cached repository "${repoUrl}" (branch "${branch}") at "${cacheDir}": ${msg}`,
      );
    }
  }

  return cacheDir;
}

#!/usr/bin/env node
import { Command } from 'commander';
import { addCommand } from './commands/add';
import { initCommand } from './commands/init';
import { listCommand } from './commands/list';
import { pullCommand } from './commands/pull';
import { statusCommand } from './commands/status';
import { upgradeCommand } from './commands/upgrade';
import { requireManifest, saveManifest } from './config';

const program = new Command();

program
  .name('dfiles')
  .description('Manage specific files/folders from multiple git repositories')
  .version('1.0.0');

// init command
program
  .command('init')
  .description('Initialize a new dfiles manifest in a directory')
  .argument('[directory]', 'target directory (default: current directory)')
  .action(async (directory: string | undefined) => {
    await initCommand(directory);
  });

// add command
program
  .command('add')
  .description('Track a file or directory from a remote git repository')
  .argument('<repo>', 'git remote URL (https:// or git@)')
  .argument('<source>', 'path within the repository to track')
  .argument('<destination>', 'local destination path (supports ~)')
  .option('-b, --branch <branch>', 'git branch to use', 'main')
  .option('--id <id>', 'custom entry identifier')
  .action(
    async (
      repo: string,
      source: string,
      destination: string,
      options: { branch: string; id?: string },
    ) => {
      await addCommand(repo, source, destination, options);
    },
  );

// pull command
program
  .command('pull')
  .description('Pull latest versions of tracked files from their remote origins')
  .argument('[ids...]', 'specific entry IDs to pull (default: all)')
  .option('--dry-run', 'show what would be pulled without making changes')
  .action(async (ids: string[], options: { dryRun?: boolean }) => {
    await pullCommand(ids, options);
  });

// status command
program
  .command('status')
  .description('Show which tracked files are current, outdated, or missing (offline)')
  .action(async () => {
    await statusCommand();
  });

// upgrade command
program
  .command('upgrade')
  .description('Upgrade dfiles to the latest published version')
  .action(async () => {
    await upgradeCommand();
  });

// list command
program
  .command('list')
  .description('List all tracked entries in the manifest')
  .option('--json', 'output as JSON')
  .action(async (options: { json?: boolean }) => {
    await listCommand(options);
  });

// remove command
program
  .command('remove')
  .description('Remove a tracked entry from the manifest by ID')
  .argument('<id>', 'entry ID to remove')
  .action(async (id: string) => {
    const { dir, manifest } = requireManifest();
    const entryIndex = manifest.entries.findIndex((entry) => entry.id === id);

    if (entryIndex === -1) {
      console.error(`Entry not found: ${id}`);
      process.exit(1);
    }

    manifest.entries.splice(entryIndex, 1);
    saveManifest(dir, manifest);
    console.log(`Removed entry '${id}'`);
  });

// Wrap execution to handle top-level async errors nicely
(async () => {
  try {
    await program.parseAsync(process.argv);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    console.error(`Error: ${message}`);
    process.exit(1);
  }
})();

import * as path from 'node:path';
import { requireManifest, saveManifest } from '../config';
import type { ManifestEntry } from '../types';

interface AddOptions {
  branch: string;
  id?: string;
}

function isPlausibleRepoUrl(repo: string): boolean {
  return repo.startsWith('https://') || repo.startsWith('git@');
}

function slugify(value: string): string {
  return value
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function repoNameFromUrl(repo: string): string {
  const trimmed = repo.replace(/\/+$/, '');
  const lastSegment = trimmed.split('/').pop() ?? trimmed;
  return lastSegment.replace(/\.git$/i, '');
}

function generateEntryId(repo: string, source: string, existingIds: Set<string>): string {
  const repoName = repoNameFromUrl(repo);
  const sourceBase = path.basename(source);
  const baseId = slugify(`${repoName}-${sourceBase}`) || 'entry';

  if (!existingIds.has(baseId)) {
    return baseId;
  }

  let suffix = 2;
  while (existingIds.has(`${baseId}-${suffix}`)) {
    suffix += 1;
  }

  return `${baseId}-${suffix}`;
}

export async function addCommand(
  repo: string,
  source: string,
  destination: string,
  options: AddOptions,
): Promise<void> {
  const { dir, manifest } = requireManifest();

  if (!isPlausibleRepoUrl(repo)) {
    throw new Error('Repository must start with "https://" or "git@".');
  }

  const duplicate = manifest.entries.find(
    (entry) => entry.repo === repo && entry.source === source && entry.destination === destination,
  );

  if (duplicate) {
    throw new Error(`Entry already exists (id: ${duplicate.id})`);
  }

  const existingIds = new Set(manifest.entries.map((entry) => entry.id));
  const requestedId = options.id?.trim();
  const id = requestedId || generateEntryId(repo, source, existingIds);

  if (existingIds.has(id)) {
    throw new Error(`Entry id already exists: ${id}`);
  }

  const newEntry: ManifestEntry = {
    id,
    repo,
    branch: options.branch || 'main',
    source,
    destination,
  };

  manifest.entries.push(newEntry);
  saveManifest(dir, manifest);

  console.log(`Added entry '${id}': ${source} from ${repo} → ${destination}`);
}

import { ensureCached } from '../cache';
import { requireManifest } from '../config';
import { syncEntry } from '../sync';
import type { ManifestEntry, PullResult } from '../types';

interface PullOptions {
  dryRun?: boolean;
}

function toErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

function selectEntries(entries: ManifestEntry[], ids: string[]): ManifestEntry[] {
  if (ids.length === 0) {
    return entries;
  }

  const byId = new Map(entries.map((entry) => [entry.id, entry]));
  for (const id of ids) {
    if (!byId.has(id)) {
      throw new Error(`Unknown entry id: ${id}`);
    }
  }

  const requestedIds = new Set(ids);
  return entries.filter((entry) => requestedIds.has(entry.id));
}

function groupByRepoAndBranch(entries: ManifestEntry[]): Map<string, ManifestEntry[]> {
  const groups = new Map<string, ManifestEntry[]>();

  for (const entry of entries) {
    const key = `${entry.repo}#${entry.branch}`;
    const group = groups.get(key);

    if (group) {
      group.push(entry);
    } else {
      groups.set(key, [entry]);
    }
  }

  return groups;
}

function printSummary(results: PullResult[]): void {
  if (results.length === 0) {
    console.log('No matching entries to pull.');
    return;
  }

  const statusWidth = Math.max(
    'unchanged'.length,
    ...results.map((result) => result.status.length),
  );
  const idWidth = Math.max(...results.map((result) => result.entry.id.length));

  for (const result of results) {
    if (result.status === 'error') {
      const errorText = result.error ?? 'Unknown error';
      console.log(
        `✗ ${'error'.padEnd(statusWidth)}  ${result.entry.id.padEnd(idWidth)}  ${errorText}`,
      );
      continue;
    }

    const marker = result.status === 'updated' ? '✓' : ' ';
    console.log(
      `${marker} ${result.status.padEnd(statusWidth)}  ${result.entry.id.padEnd(idWidth)}  ${result.entry.destination}`,
    );
  }
}

export async function pullCommand(ids: string[], options: PullOptions): Promise<void> {
  const { manifest } = requireManifest();
  const selectedEntries = selectEntries(manifest.entries, ids);
  const groups = groupByRepoAndBranch(selectedEntries);
  const results: PullResult[] = [];

  for (const groupEntries of groups.values()) {
    if (groupEntries.length === 0) {
      continue;
    }

    if (options.dryRun) {
      for (const entry of groupEntries) {
        console.log(
          `[dry-run] Would pull ${entry.source} from ${entry.repo} → ${entry.destination}`,
        );
        results.push({ entry, status: 'unchanged' });
      }
      continue;
    }

    let cacheDir: string;
    try {
      const first = groupEntries[0];
      cacheDir = await ensureCached(first.repo, first.branch);
    } catch (error) {
      const message = toErrorMessage(error);
      for (const entry of groupEntries) {
        results.push({
          entry,
          status: 'error',
          error: message,
        });
      }
      continue;
    }

    for (const entry of groupEntries) {
      try {
        const status = await syncEntry(entry, cacheDir);
        results.push({ entry, status });
      } catch (error) {
        results.push({
          entry,
          status: 'error',
          error: toErrorMessage(error),
        });
      }
    }
  }

  printSummary(results);

  if (results.some((result) => result.status === 'error')) {
    process.exit(1);
  }
}

import { spawn } from 'node:child_process';

export async function upgradeCommand(): Promise<void> {
  await new Promise<void>((resolve, reject) => {
    const installer = spawn('npm', ['install', '--global', '@madkoo/dfiles@latest'], {
      stdio: 'inherit',
      shell: process.platform === 'win32',
    });

    installer.on('error', reject);
    installer.on('close', (code) => {
      if (code !== 0) {
        reject(new Error(`npm install failed with exit code ${code}`));
        return;
      }

      console.log('dfiles upgrade complete.');
      resolve();
    });
  });
}

/** One tracked file/directory entry in the manifest */
export interface ManifestEntry {
  /** Stable identifier, e.g. "canvas-design-skill" */
  id: string;
  /** Full remote URL: "https://github.com/org/repo" or "git@github.com:org/repo.git" */
  repo: string;
  /** Git branch, default "main" */
  branch: string;
  /** Repo-relative path, directory, or glob pattern: "skills/canvas-design/SKILL.md" or "skills/canvas-design/**" */
  source: string;
  /** Absolute or ~-prefixed local destination path */
  destination: string;
}

/** The dfiles.json file schema */
export interface Manifest {
  version: 1;
  entries: ManifestEntry[];
}

/** Result of a single pull operation */
export interface PullResult {
  entry: ManifestEntry;
  status: 'updated' | 'unchanged' | 'error';
  error?: string;
}

/** Result of a single status check (offline) */
export interface StatusResult {
  entry: ManifestEntry;
  state: 'current' | 'outdated' | 'missing';
}

